091f\u093e\u0938\u0947\u091f \u0938\u0947 \u092c\u0947\u0938\u093f\u0915 \u0906\u0923\u0935\u093f\u0915 \u0917\u0941\u0923\u094b\u0902 \u0915\u0947 \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923 \u090f\u0935\u0902 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0915\u093e \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u092a\u094d\u0930\u092f\u094b\u0917 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 (Complete Experiment Design)\n\n---\n\n## 1. \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u093e \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f \u090f\u0935\u0902 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0914\u091a\u093f\u0924\u094d\u092f (Scientific Objective & Rationale)\n\n### 1.1 \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f\n\u0907\u0938 \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u093e \u092e\u0941\u0916\u094d\u092f \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f \u090f\u0915 \u092c\u093e\u092f\u094b\u090f\u0915\u094d\u091f\u093f\u0935/\u0921\u094d\u0930\u0917-\u0932\u093e\u0907\u0915 \u0930\u093e\u0938\u093e\u092f\u0928\u093f\u0915 \u0921\u0947\u091f\u093e\u0938\u0947\u091f (\u0909\u0926\u093e. ChEMBL \u092f\u093e PubChem \u0915\u093e \u0915\u094d\u092f\u0942\u0930\u0947\u091f\u0947\u0921 \u0938\u092c\u0938\u0947\u091f) \u0938\u0947 1D \u0914\u0930 2D \u092b\u093f\u091c\u093f\u0915\u094b\u0915\u0947\u092e\u093f\u0915\u0932 \u0906\u0923\u0935\u093f\u0915 \u0917\u0941\u0923\u094b\u0902 (Physicochemical Molecular Descriptors) \u0915\u093e \u0938\u091f\u0940\u0915 \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923, \u0938\u0902\u0930\u091a\u0928\u093e \u092e\u093e\u0928\u0915\u0940\u0915\u0930\u0923, \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0914\u0930 \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0915\u0930\u0928\u093e \u0939\u0948\u0964\n\n### 1.2 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0914\u091a\u093f\u0924\u094d\u092f (Rationale)\n- **\u0914\u0937\u0927-\u0905\u0928\u0941\u0915\u0942\u0932\u0924\u093e \u0915\u093e \u0906\u0915\u0932\u0928 (Drug-Likeness Assessment):** \u092e\u094c\u0916\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0938\u0915\u094d\u0930\u093f\u092f \u0926\u0935\u093e\u0913\u0902 \u0915\u0947 \u0905\u0935\u0936\u094b\u0937\u0923 \u0914\u0930 \u091c\u0948\u0935\u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e (Oral Bioavailability) \u0915\u094b \u0938\u092e\u091d\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0932\u093f\u092a\u093f\u0928\u0938\u094d\u0915\u0940 \u0915\u0947 \"\u0930\u0942\u0932 \u0911\u092b \u092b\u093e\u0907\u0935\" (Lipinski's Rule of 5 - Ro5) \u0914\u0930 \u0935\u0947\u092c\u0930 \u0915\u0947 \u0928\u093f\u092f\u092e\u094b\u0902 (Veber's Rules) \u0915\u093e \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092c\u0941\u0928\u093f\u092f\u093e\u0926\u0940 \u092e\u093e\u0928\u0915 \u0939\u0948\u0964\n- **\u0930\u093e\u0938\u093e\u092f\u0928\u093f\u0915 \u0938\u094d\u0925\u093e\u0928 \u0915\u0940 \u0938\u092e\u091d (Chemical Space Exploration):** \u0906\u0923\u0935\u093f\u0915 \u092d\u093e\u0930 (MW), \u0932\u093f\u092a\u094b\u092b\u093f\u0932\u093f\u0938\u093f\u091f\u0940 (LogP), \u0939\u093e\u0907\u0921\u094d\u0930\u094b\u091c\u0928 \u092c\u0949\u0928\u094d\u0921\u093f\u0902\u0917 \u0915\u094d\u0937\u092e\u0924\u093e (HBD/HBA), \u0914\u0930 \u0927\u094d\u0930\u0941\u0935\u0940\u092f \u0938\u0924\u0939 \u0915\u094d\u0937\u0947\u0924\u094d\u0930 (TPSA) \u091c\u0948\u0938\u0947 \u0917\u0941\u0923 \u092f\u0939 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0915\u093f \u092f\u094c\u0917\u093f\u0915 \u091c\u0948\u0935\u093f\u0915 \u091d\u093f\u0932\u094d\u0932\u093f\u092f\u094b\u0902 (biological membranes) \u0915\u094b \u092a\u093e\u0930 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902 \u092f\u093e \u0928\u0939\u0940\u0902\u0964\n- **\u0921\u0947\u091f\u093e-\u0921\u094d\u0930\u093f\u0935\u0928 \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u093f\u0902\u0917 (Virtual Screening Foundation):** \u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u091a\u0930\u0923 \u092e\u0947\u0902 \u0905\u0935\u093e\u0902\u091b\u093f\u0924 (non-druglike, reactive, \u092f\u093e \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0939\u093e\u0907\u0921\u094d\u0930\u094b\u092b\u094b\u092c\u093f\u0915) \u0905\u0923\u0941\u0913\u0902 \u0915\u094b \u091b\u093e\u0928\u0915\u0930 \u092c\u093e\u0939\u0930 \u0915\u0930\u0928\u0947 \u0938\u0947 \u0906\u0917\u093e\u092e\u0940 \u091c\u0948\u0935\u093f\u0915 \u092a\u0930\u0940\u0915\u094d\u0937\u0923\u094b\u0902 \u0914\u0930 \u092e\u0936\u0940\u0928 \u0932\u0930\u094d\u0928\u093f\u0902\u0917 (QSPR/QSAR) \u092e\u0949\u0921\u0932\u093f\u0902\u0917 \u0915\u0940 \u0938\u091f\u0940\u0915\u0924\u093e \u092c\u0922\u093c\u0924\u0940 \u0939\u0948\u0964\n\n---\n\n## 2. \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0935\u093f\u0928\u093f\u0930\u094d\u0926\u0947\u0936 \u090f\u0935\u0902 \u0907\u0928\u092a\u0941\u091f \u092a\u094d\u0930\u093e\u0930\u0942\u092a (Dataset Specification)\n\n- **\u0938\u094d\u0930\u094b\u0924:** ChEMBL (Bioactive small molecules) \u092f\u093e PubChem Compound \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0915\u093e \u090f\u0915 \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f \u0938\u092c-\u0938\u0948\u0902\u092a\u0932 (\u0909\u0926\u093e. $N = 10,000$ \u0938\u0947 $50,000$ \u092f\u094c\u0917\u093f\u0915)\u0964\n- **\u0907\u0928\u092a\u0941\u091f \u092a\u094d\u0930\u093e\u0930\u0942\u092a:** \u0938\u093e\u0930\u0923\u0940\u092c\u0926\u094d\u0927 CSV/TSV \u092b\u093c\u093e\u0907\u0932, \u091c\u093f\u0938\u092e\u0947\u0902 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0905\u0923\u0941 \u0915\u0947 \u0932\u093f\u090f \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u092b\u093c\u0940\u0932\u094d\u0921 \u0936\u093e\u092e\u093f\u0932 \u0939\u094b\u0902:\n  - `Compound_ID`: \u0935\u093f\u0936\u093f\u0937\u094d\u091f \u092a\u0939\u091a\u093e\u0928\u0915\u0930\u094d\u0924\u093e (\u0909\u0926\u093e. ChEMBL ID / CID)\u0964\n  - `SMILES`: \u0938\u0902\u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 (Simplified Molecular Input Line Entry System)\u0964\n  - \u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 \u092e\u0947\u091f\u093e\u0921\u0947\u091f\u093e: \u0932\u0915\u094d\u0937\u094d\u092f \u092a\u094d\u0930\u094b\u091f\u0940\u0928 \u092f\u093e \u092c\u093e\u092f\u094b\u090f\u0915\u094d\u091f\u093f\u0935\u093f\u091f\u0940 \u0935\u0930\u094d\u0917 (\u092f\u0926\u093f \u0909\u092a\u0932\u092c\u094d\u0927 \u0939\u094b)\u0964\n\n---\n\n## 3. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0915\u093e\u0930\u094d\u092f\u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u090f\u0935\u0902 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 (Experimental Methodology)\n\n\u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u094b \u091a\u093e\u0930 \u0938\u094d\u092a\u0937\u094d\u091f \u091a\u0930\u0923\u094b\u0902 \u092e\u0947\u0902 \u0938\u0902\u0930\u091a\u093f\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948:\n\n### \u091a\u0930\u0923 1: \u092a\u093e\u0930\u094d\u0938\u093f\u0902\u0917 \u090f\u0935\u0902 \u0938\u0902\u0930\u091a\u0928\u093e \u092e\u093e\u0928\u0915\u0940\u0915\u0930\u0923 (Structure Curation & Standardization)\n1. **SMILES \u092a\u093e\u0930\u094d\u0938\u093f\u0902\u0917:** RDKit (`Chem.MolFromSmiles`) \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 SMILES \u0938\u094d\u091f\u094d\u0930\u093f\u0902\u0917\u094d\u0938 \u0915\u094b 2D \u0906\u0923\u0935\u093f\u0915 \u0917\u094d\u0930\u093e\u092b \u092e\u0947\u0902 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n2. **\u0921\u093f\u0938\u0949\u0932\u094d\u091f\u093f\u0902\u0917 (Desalting):** \u092f\u094c\u0917\u093f\u0915\u094b\u0902 \u092e\u0947\u0902 \u0909\u092a\u0938\u094d\u0925\u093f\u0924 \u0915\u093e\u0909\u0902\u091f\u0930-\u0906\u092f\u0928\u094b\u0902 \u0914\u0930 \u0935\u093f\u0932\u093e\u092f\u0915\u094b\u0902 (\u0909\u0926\u093e. $Na^+$, $Cl^-$, $H_2O$) \u0915\u094b \u0939\u091f\u093e\u0928\u093e \u0924\u0925\u093e \u0915\u0947\u0935\u0932 \u0938\u092c\u0938\u0947 \u092c\u0921\u093c\u0947 \u0915\u093e\u0930\u094d\u092c\u0928\u093f\u0915 \u0916\u0902\u0921 (largest covalent fragment) \u0915\u094b \u0938\u0902\u0930\u0915\u094d\u0937\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n3. **\u091a\u093e\u0930\u094d\u091c \u0928\u094d\u092f\u0942\u091f\u094d\u0930\u0932\u093e\u0907\u091c\u0947\u0936\u0928 (Charge Neutralization):** \u092e\u093e\u0928\u0915 \u092b\u093f\u091c\u093f\u0915\u094b\u0915\u0947\u092e\u093f\u0915\u0932 \u0917\u0923\u0928\u093e\u0913\u0902 \u0915\u0940 \u090f\u0915\u0930\u0942\u092a\u0924\u093e \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u094b\u091f\u094b\u0928\u0947\u0936\u0928 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 \u0915\u093e \u092e\u093e\u0928\u0915\u0940\u0915\u0930\u0923 (\u0909\u0926\u093e. \u0915\u093e\u0930\u094d\u092c\u094b\u0915\u094d\u0938\u093f\u0932\u0947\u091f \u0906\u092f\u0928\u094b\u0902 \u0915\u094b \u0928\u094d\u092f\u0942\u091f\u094d\u0930\u0932 \u0930\u0942\u092a \u092e\u0947\u0902 \u0932\u093e\u0928\u093e \u091c\u0939\u093e\u0901 \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u094b)\u0964\n4. **\u0915\u0948\u0928\u094b\u0928\u093f\u0915\u0932\u093e\u0907\u091c\u0947\u0936\u0928 \u0914\u0930 \u091f\u0949\u091f\u094b\u092e\u0930 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u0923:** RDKit \u0915\u0947 `MolStandardize` \u092e\u0949\u0921\u094d\u092f\u0942\u0932 \u0926\u094d\u0935\u093e\u0930\u093e \u092e\u093e\u0928\u0915\u0940\u0915\u0943\u0924 \u0915\u0948\u0928\u094b\u0928\u093f\u0915\u0932 \u092b\u0949\u0930\u094d\u092e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u093e\u0964\n\n### \u091a\u0930\u0923 2: 1D/2D \u092b\u093f\u091c\u093f\u0915\u094b\u0915\u0947\u092e\u093f\u0915\u0932 \u0921\u093f\u0938\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u0930\u094d\u0938 \u0915\u093e \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923 (Descriptor Extraction)\n\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092e\u093e\u0928\u094d\u092f \u0905\u0923\u0941 \u0915\u0947 \u0932\u093f\u090f \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u092c\u0941\u0928\u093f\u092f\u093e\u0926\u0940 \u0906\u0923\u0935\u093f\u0915 \u0917\u0941\u0923\u094b\u0902 \u0915\u0940 \u0917\u0923\u0928\u093e \u0915\u0940 \u091c\u093e\u090f\u0917\u0940:\n- **\u0906\u0923\u0935\u093f\u0915 \u092d\u093e\u0930 (Molecular Weight - MW):** \u0914\u0938\u0924 \u0906\u0923\u0935\u093f\u0915 \u0926\u094d\u0930\u0935\u094d\u092f\u092e\u093e\u0928 (g/mol)\u0964\n- **\u0935\u093f\u092d\u093e\u091c\u0928 \u0917\u0941\u0923\u093e\u0902\u0915 (Wildman-Crippen SlogP):** \u0911\u0915\u094d\u091f\u0947\u0928\u0949\u0932-\u091c\u0932 \u0935\u093f\u092d\u093e\u091c\u0928 \u0917\u0941\u0923\u093e\u0902\u0915 (Lipophilicity)\u0964\n- **\u0939\u093e\u0907\u0921\u094d\u0930\u094b\u091c\u0928 \u092c\u0949\u0928\u094d\u0921 \u0921\u094b\u0928\u0930 (HBD):** $O-H$ \u0914\u0930 $N-H$ \u0938\u092e\u0942\u0939\u094b\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094d\u092f\u093e\u0964\n- **\u0939\u093e\u0907\u0921\u094d\u0930\u094b\u091c\u0928 \u092c\u0949\u0928\u094d\u0921 \u090f\u0915\u094d\u0938\u0947\u092a\u094d\u091f\u0930 (HBA):** $O$ \u0914\u0930 $N$ \u092a\u0930\u092e\u093e\u0923\u0941\u0913\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094d\u092f\u093e\u0964\n- **\u091f\u094b\u092a\u094b\u0932\u0949\u091c\u093f\u0915\u0932 \u092a\u094b\u0932\u0930 \u0938\u0930\u092b\u0947\u0938 \u090f\u0930\u093f\u092f\u093e (TPSA):** \u0927\u094d\u0930\u0941\u0935\u0940\u092f \u092a\u0930\u092e\u093e\u0923\u0941\u0913\u0902 (\u0911\u0915\u094d\u0938\u0940\u091c\u0928, \u0928\u093e\u0907\u091f\u094d\u0930\u094b\u091c\u0928 \u0914\u0930 \u0909\u0928\u0915\u0947 \u0938\u0902\u0932\u0917\u094d\u0928 \u0939\u093e\u0907\u0921\u094d\u0930\u094b\u091c\u0928) \u0926\u094d\u0935\u093e\u0930\u093e \u0918\u0947\u0930\u093e \u0917\u092f\u093e \u0938\u0924\u0939\u0940 \u0915\u094d\u0937\u0947\u0924\u094d\u0930\u092b\u0932 ($\\text{\u00c5}^2$ \u092e\u0947\u0902)\u0964\n- **\u0918\u0942\u0930\u094d\u0923\u0928\u0936\u0940\u0932 \u092c\u0902\u0927 (Rotatable Bonds - NumRotBonds):** \u0905\u0923\u0941 \u0915\u0947 \u0932\u091a\u0940\u0932\u0947\u092a\u0928 (molecular flexibility) \u0915\u093e \u092e\u093e\u092a\u0964\n- **\u092d\u093e\u0930\u0940 \u092a\u0930\u092e\u093e\u0923\u0941\u0913\u0902 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e (Heavy Atom Count - HAC):** \u0917\u0948\u0930-\u0939\u093e\u0907\u0921\u094d\u0930\u094b\u091c\u0928 \u092a\u0930\u092e\u093e\u0923\u0941\u0913\u0902 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e\u0964\n- **$Fsp^3$ (Fraction of $sp^3$ carbons):** 3D \u091c\u091f\u093f\u0932\u0924\u093e \u0914\u0930 \u0938\u0902\u0924\u0943\u092a\u094d\u0924\u093f \u0915\u093e \u092e\u093e\u092a ($sp^3$ \u0915\u093e\u0930\u094d\u092c\u0928 / \u0915\u0941\u0932 \u0915\u093e\u0930\u094d\u092c\u0928)\u0964\n- **\u0932\u093f\u092a\u093f\u0928\u0938\u094d\u0915\u0940 \u0909\u0932\u094d\u0932\u0902\u0918\u0928 \u0917\u0923\u0928\u093e (Lipinski Rule of 5 Violations):** \n  - $MW \\le 500$ Da\n  - $\\text{LogP} \\le 5$\n  - $\\text{HBD} \\le 5$\n  - $\\text{HBA} \\le 10$\n  (\u0909\u0932\u094d\u0932\u093f\u0916\u093f\u0924 4 \u092e\u093e\u092a\u0926\u0902\u0921\u094b\u0902 \u092e\u0947\u0902 \u0938\u0947 \u0909\u0932\u094d\u0932\u0902\u0918\u0928\u094b\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094d\u092f\u093e, 0 \u0938\u0947 4)\u0964\n- **\u0935\u0947\u092c\u0930 \u0905\u0928\u0941\u092a\u093e\u0932\u0928 (Veber Compliance):** $\\text{Rotatable Bonds} \\le 10$ \u0914\u0930 $\\text{TPSA} \\le 140\\text{ \u00c5}^2$\u0964\n\n---\n\n## 4. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0935 \u0921\u0947\u091f\u093e \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Controls & Quality Assurance)\n\n\u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u0940 \u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f\u0924\u093e \u0914\u0930 \u0936\u0941\u0926\u094d\u0927\u0924\u093e \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902:\n\n### 4.1 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Positive Controls / Reference Standards)\n\u091c\u094d\u091e\u093e\u0924, \u0938\u093e\u0939\u093f\u0924\u094d\u092f-\u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0917\u0941\u0923\u094b\u0902 \u0935\u093e\u0932\u0947 3 \u092e\u093e\u0928\u0915 \u0938\u0902\u0926\u0930\u094d\u092d \u0905\u0923\u0941\u0913\u0902 \u0915\u094b \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u094b\u0938\u0947\u0938 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e:\n1. **\u090f\u0938\u094d\u092a\u093f\u0930\u093f\u0928 (Aspirin - `CC(=O)Oc1ccccc1C(=O)O`):**\n   - \u0905\u092a\u0947\u0915\u094d\u0937\u093f\u0924 \u092e\u093e\u0928: $\\text{MW} \\approx 180.16\\text{ g/mol}$, $\\text{SlogP} \\approx 1.31$, $\\text{HBD} = 1$, $\\text{HBA} = 3$, $\\text{TPSA} \\approx 63.6\\text{ \\AA}^2$, Ro5 \u0909\u0932\u094d\u0932\u0902\u0918\u0928 $= 0$\u0964\n2. **\u0915\u0948\u092b\u0940\u0928 (Caffeine - `Cn1cnc2c1c(=O)n(c(=O)n2C)C`):**\n   - \u0905\u092a\u0947\u0915\u094d\u0937\u093f\u0924 \u092e\u093e\u0928: $\\text{MW} \\approx 194.19\\text{ g/mol}$, $\\text{SlogP} \\approx -0.07$, $\\text{HBD} = 0$, $\\text{HBA} = 6$, $\\text{TPSA} \\approx 61.8\\text{ \\AA}^2$, Ro5 \u0909\u0932\u094d\u0932\u0902\u0918\u0928 $= 0$\u0964\n3. **\u092a\u0948\u0930\u093e\u0938\u093f\u091f\u093e\u092e\u094b\u0932 (Paracetamol - `CC(=O)Nc1ccc(O)cc1`):**\n   - \u0905\u092a\u0947\u0915\u094d\u0937\u093f\u0924 \u092e\u093e\u0928: $\\text{MW} \\approx 151.16\\text{ g/mol}$, $\\text{SlogP} \\approx 1.35$, $\\text{HBD} = 2$, $\\text{HBA} = 2$, $\\text{TPSA} \\approx 49.3\\text{ \\AA}^2$, Ro5 \u0909\u0932\u094d\u0932\u0902\u0918\u0928 $= 0$\u0964\n- *\u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0915\u0938\u094c\u091f\u0940:* \u0917\u0923\u0928\u093e \u0915\u093f\u090f \u0917\u090f \u092e\u093e\u0928\u094b\u0902 \u0915\u094b \u0907\u0928 \u092e\u093e\u0928\u0915 \u0938\u0902\u0926\u0930\u094d\u092d \u092e\u093e\u0928\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u0936\u0942\u0928\u094d\u092f-\u0938\u0939\u0928\u0936\u0940\u0932\u0924\u093e (zero tolerance, \u0926\u0936\u092e\u0932\u0935 \u0915\u0947 2 \u0938\u094d\u0925\u093e\u0928\u094b\u0902 \u0924\u0915) \u0915\u0947 \u0938\u093e\u0925 \u092e\u0947\u0932 \u0916\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n\n### 4.2 \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u090f\u0935\u0902 \u090f\u091c-\u0915\u0947\u0938 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Negative Controls & Edge-Case Handling)\n- **\u0905\u092e\u093e\u0928\u094d\u092f SMILES (Syntactically invalid SMILES):** \u0909\u0926\u093e. \u0905\u0938\u0902\u0924\u0941\u0932\u093f\u0924 \u092c\u094d\u0930\u0948\u0915\u0947\u091f `CC(=O` \u092f\u093e \u0916\u0941\u0932\u0947 \u0930\u093f\u0902\u0917 `c1ccccc`\u0964 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u094b \u0915\u094d\u0930\u0948\u0936 \u0939\u0941\u090f \u092c\u093f\u0928\u093e \u0907\u0928\u094d\u0939\u0947\u0902 \u092a\u0915\u0921\u093c\u0928\u093e \u091a\u093e\u0939\u093f\u090f \u0914\u0930 '\u092a\u093e\u0930\u094d\u0938\u093f\u0902\u0917 \u0924\u094d\u0930\u0941\u091f\u093f' \u0932\u0949\u0917 \u0915\u0930\u0928\u0940 \u091a\u093e\u0939\u093f\u090f\u0964\n- **\u0936\u0941\u0926\u094d\u0927 \u0905\u0915\u093e\u0930\u094d\u092c\u0928\u093f\u0915 \u0905\u0923\u0941 (Inorganic compounds):** \u0909\u0926\u093e. `[Na+].[Cl-]` \u092f\u093e \u0938\u093f\u0932\u093f\u0915\u093e \u092f\u094c\u0917\u093f\u0915\u0964 \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0915\u094b \u092b\u093c\u093f\u0932\u094d\u091f\u0930\u093f\u0902\u0917 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0915\u093e\u0930\u094d\u092c\u0928-\u0930\u0939\u093f\u0924 \u092f\u094c\u0917\u093f\u0915\u094b\u0902 \u0915\u094b \u091a\u093f\u0939\u094d\u0928\u093f\u0924/\u0905\u0932\u0917 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n- **\u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u092c\u0921\u093c\u0947 \u092e\u0948\u0915\u094d\u0930\u094b\u0938\u093e\u092f\u0915\u0932 \u092f\u093e \u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921\u094d\u0938:** Ro5 \u0909\u0932\u094d\u0932\u0902\u0918\u0928 \u0938\u0940\u092e\u093e (Ro5 violations $\\ge 2$) \u0915\u0947 \u0935\u094d\u092f\u0935\u0939\u093e\u0930 \u0915\u094b \u092a\u0930\u0916\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f\u0964\n\n### 4.3 \u0921\u0947\u091f\u093e \u0905\u0916\u0902\u0921\u0924\u093e \u0914\u0930 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Integrity Metrics)\n- \u092a\u093e\u0930\u094d\u0938\u093f\u0902\u0917 \u0935\u093f\u092b\u0932\u0924\u093e \u0926\u0930 (Parsing failure rate) $< 1.0\\%$ \u0939\u094b\u0928\u0940 \u091a\u093e\u0939\u093f\u090f\u0964\n- \u0915\u094b\u0908 \u092d\u0940 `NaN` \u092f\u093e `Null` \u092e\u093e\u0928 \u0905\u0902\u0924\u093f\u092e \u092a\u0930\u093f\u0923\u093e\u092e \u0924\u093e\u0932\u093f\u0915\u093e \u092e\u0947\u0902 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n## 5. \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Statistical Analysis Plan)\n\n\u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923 \u0915\u0947 \u092a\u0936\u094d\u091a\u093e\u0924 \u0921\u0947\u091f\u093e \u0915\u093e \u092c\u0939\u0941-\u091a\u0930\u0923\u0940\u092f \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e:\n\n1. **\u0935\u0930\u094d\u0923\u0928\u093e\u0924\u094d\u092e\u0915 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940 (Descriptive Summary):**\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0917\u0941\u0923\u0927\u0930\u094d\u092e (MW, LogP, TPSA, HBD, HBA, RotBonds) \u0915\u0947 \u0932\u093f\u090f \u092e\u0940\u0928 (Mean), \u092e\u0940\u0921\u093f\u092f\u0928 (Median), \u092e\u093e\u0928\u0915 \u0935\u093f\u091a\u0932\u0928 (Standard Deviation), \u0907\u0902\u091f\u0930\u0915\u094d\u0935\u093e\u0930\u094d\u091f\u093e\u0907\u0932 \u0930\u0947\u0902\u091c (IQR), \u0924\u093f\u0930\u091b\u093e\u092a\u0928 (Skewness), \u0914\u0930 \u0915\u0930\u094d\u091f\u094b\u0938\u093f\u0938 (Kurtosis)\u0964\n2. **\u0935\u093f\u0924\u0930\u0923 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Distribution Profiles):**\n   - \u0939\u093f\u0938\u094d\u091f\u094b\u0917\u094d\u0930\u093e\u092e\u094d\u0938 \u0914\u0930 \u0915\u0930\u094d\u0928\u0947\u0932 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 \u090f\u0938\u094d\u091f\u0940\u092e\u0947\u0936\u0928 (KDE) \u092a\u094d\u0932\u0949\u091f \u0926\u094d\u0935\u093e\u0930\u093e \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0921\u093f\u0938\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u0930 \u0915\u0947 \u092b\u0948\u0932\u093e\u0935 \u0915\u0940 \u091c\u093e\u0902\u091a\u0964\n   - \u0906\u0909\u091f\u0932\u093e\u092f\u0930\u094d\u0938 \u0915\u0940 \u092a\u0939\u091a\u093e\u0928 \u0939\u0947\u0924\u0941 \u092c\u0949\u0915\u094d\u0938 \u092a\u094d\u0932\u0949\u091f\u094d\u0938 (Tukey's $1.5 \\times \\text{IQR}$ \u0928\u093f\u092f\u092e)\u0964\n3. **\u0938\u0939\u0938\u0902\u092c\u0902\u0927 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Correlation Analysis):**\n   - \u092a\u093f\u092f\u0930\u094d\u0938\u0928 (Pearson) \u0914\u0930 \u0938\u094d\u092a\u0940\u092f\u0930\u092e\u0948\u0928 \u0930\u0948\u0902\u0915 (Spearman rank) \u0938\u0939\u0938\u0902\u092c\u0902\u0927 \u092e\u0948\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0915\u093e \u0928\u093f\u0930\u094d\u092e\u093e\u0923\u0964\n   - \u0939\u0940\u091f\u092e\u0948\u092a \u0935\u093f\u091c\u093c\u0941\u0905\u0932\u093e\u0907\u091c\u093c\u0947\u0936\u0928 (\u0935\u093f\u0936\u0947\u0937 \u0930\u0942\u092a \u0938\u0947 MW \u092c\u0928\u093e\u092e TPSA, MW \u092c\u0928\u093e\u092e LogP, \u0914\u0930 HBD \u092c\u0928\u093e\u092e TPSA \u0915\u0947 \u092e\u0927\u094d\u092f \u092e\u0932\u094d\u091f\u0940\u0915\u094b\u0932\u093f\u0928\u093f\u090f\u0930\u093f\u091f\u0940 \u0915\u0940 \u092a\u0939\u091a\u093e\u0928)\u0964\n4. **\u0915\u0947\u092e\u093f\u0915\u0932 \u0938\u094d\u092a\u0947\u0938 \u090f\u0935\u0902 \u0906\u092f\u093e\u092e\u0940\u092f\u0924\u093e \u092e\u0947\u0902 \u0915\u092e\u0940 (Chemical Space Dimensionality Reduction):**\n   - \u092e\u093e\u0928\u0915\u0940\u0915\u0943\u0924 \u092e\u093e\u0928\u094b\u0902 (Z-score normalization / `StandardScaler`) \u092a\u0930 \u092a\u094d\u0930\u093f\u0902\u0938\u093f\u092a\u0932 \u0915\u0902\u092a\u094b\u0928\u0947\u0902\u091f \u090f\u0928\u093e\u0932\u093f\u0938\u093f\u0938 (PCA)\u0964\n   - \u092a\u094d\u0930\u0925\u092e \u0926\u094b \u092e\u0941\u0916\u094d\u092f \u0918\u091f\u0915\u094b\u0902 (PC1 \u0914\u0930 PC2) \u092a\u0930 \u0938\u0902\u091a\u093f\u0924 \u0935\u094d\u092f\u093e\u0916\u094d\u092f\u093e\u092f\u093f\u0924 \u092d\u093f\u0928\u094d\u0928\u0924\u093e (Cumulative Explained Variance) \u0915\u093e \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u0923 \u0914\u0930 2D \u0915\u0947\u092e\u093f\u0915\u0932 \u0938\u094d\u092a\u0947\u0938 \u0938\u094d\u0915\u0948\u091f\u0930 \u092a\u094d\u0932\u0949\u091f\u0964\n5. **\u0921\u094d\u0930\u0917-\u0932\u093e\u0907\u0915\u0928\u0947\u0938 \u0905\u0928\u0941\u092a\u093e\u0932\u0928 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 (Compliance Proportion Analysis):**\n   - \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u092e\u0947\u0902 Ro5 \u0915\u093e \u092a\u0942\u0930\u094d\u0923 \u092a\u093e\u0932\u0928 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 \u092f\u094c\u0917\u093f\u0915\u094b\u0902 (0 \u0909\u0932\u094d\u0932\u0902\u0918\u0928), \u092e\u0927\u094d\u092f\u092e (1 \u0909\u0932\u094d\u0932\u0902\u0918\u0928), \u0914\u0930 \u0917\u0948\u0930-\u0905\u0928\u0941\u092a\u093e\u0932\u0928 \u0935\u093e\u0932\u0947 ( $\\ge 2$ \u0909\u0932\u094d\u0932\u0902\u0918\u0928) \u0915\u093e \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0905\u0928\u0941\u092a\u093e\u0924 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n\n---\n\n## 6. \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e \u0914\u0930 \u0924\u0915\u0928\u0940\u0915\u0940 \u0938\u0902\u0938\u093e\u0927\u0928 (Feasibility & Resource Assessment)\n\n- **\u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e:** 1D/2D \u092b\u093f\u091c\u093f\u0915\u094b\u0915\u0947\u092e\u093f\u0915\u0932 \u0921\u093f\u0938\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u0930\u094d\u0938 \u0915\u0940 \u0917\u0923\u0928\u093e \u0935\u093f\u0936\u0941\u0926\u094d\u0927 \u0930\u0942\u092a \u0938\u0947 \u092c\u0940\u091c\u0917\u0923\u093f\u0924\u0940\u092f \u0914\u0930 \u0917\u094d\u0930\u093e\u092b-\u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964 $50,000$ \u0905\u0923\u0941\u0913\u0902 \u0915\u0947 \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0915\u0947 \u0932\u093f\u090f \u0917\u0923\u0928\u093e \u0938\u092e\u092f \u092e\u0932\u094d\u091f\u0940\u092a\u094d\u0930\u0949\u0938\u0947\u0938\u093f\u0902\u0917 (\u0909\u0926\u093e. 8-16 \u0915\u094b\u0930) \u0915\u0947 \u0938\u093e\u0925 2 \u0938\u0947 5 \u092e\u093f\u0928\u091f \u0915\u0947 \u092d\u0940\u0924\u0930 \u0938\u0902\u092d\u0935 \u0939\u0948\u0964\n- **\u092e\u0947\u092e\u094b\u0930\u0940 \u0914\u0930 \u0938\u094d\u091f\u094b\u0930\u0947\u091c:** \u092a\u0942\u0930\u094d\u0923 \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0914\u0930 \u0935\u094d\u092f\u0941\u0924\u094d\u092a\u0928\u094d\u0928 \u0917\u0941\u0923\u0927\u0930\u094d\u092e\u094b\u0902 \u0915\u0940 \u0938\u093e\u0930\u0923\u0940 \u0915\u0947 \u0932\u093f\u090f $< 500\\text{ MB}$ \u0930\u0948\u092e \u0914\u0930 \u0938\u094d\u091f\u094b\u0930\u0947\u091c \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0939\u094b\u0917\u0940\u0964\n- **\u0938\u0949\u092b\u094d\u091f\u0935\u0947\u092f\u0930 \u0938\u094d\u091f\u0948\u0915:** Python 3.9+, RDKit (Chemoinformatics), Pandas/NumPy (\u0921\u0947\u091f\u093e \u0939\u0948\u0902\u0921\u0932\u093f\u0902\u0917), SciPy/Scikit-learn (\u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940 \u0935 PCA), Seaborn/Matplotlib (\u0935\u093f\u091c\u093c\u0941\u0905\u0932\u093e\u0907\u091c\u093c\u0947\u0936\u0928)\u0964\n\n---\n\n## 7. \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\n\u092f\u0939 \u092a\u094d\u0930\u092f\u094b\u0917 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u092c\u093e\u092f\u094b\u090f\u0915\u094d\u091f\u093f\u0935 \u0930\u093e\u0938\u093e\u092f\u0928\u093f\u0915 \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0938\u0947 \u0906\u0923\u0935\u093f\u0915 \u0917\u0941\u0923\u094b\u0902 \u0915\u0947 \u092e\u093e\u0928\u0915\u0940\u0915\u0943\u0924 \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923, \u0915\u0920\u094b\u0930 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (\u092a\u0949\u091c\u093f\u091f\u093f\u0935 \u0935 \u0928\u0947\u0917\u0947\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0938), \u0914\u0930 \u0917\u0939\u0928 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u094d\u092f\u093e\u0916\u094d\u092f\u093e \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u092e\u091c\u092c\u0942\u0924, \u092a\u0941\u0928\u0930\u0941\u0924\u094d\u092a\u093e\u0926\u0915 \u0914\u0930 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0938\u0941\u0926\u0943\u0922\u093c \u0922\u093e\u0902\u091a\u093e \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u0930\u0924\u093e \u0939\u0948\u0964", "uncertainties": ["\u0921\u0947\u091f\u093e\u0938\u0947\u091f \u092e\u0947\u0902 \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0906\u092f\u0928\u0940\u0915\u0930\u0923 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 (tautomers/protomers at physiological pH 7.4) \u0915\u0947 \u0932\u093f\u090f \u0935\u093f\u0936\u093f\u0937\u094d\u091f pH-\u092e\u0949\u0921\u0932\u093f\u0902\u0917 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0928\u093e \u0939\u0948 \u092f\u093e \u092e\u093e\u0928\u0915 \u0928\u094d\u092f\u0942\u091f\u094d\u0930\u0932\u093e\u0907\u091c\u094d\u0921 \u092e\u0949\u0932\u093f\u0915\u094d\u092f\u0942\u0932\u0930 \u0917\u094d\u0930\u093e\u092b \u092a\u0930 \u0928\u093f\u0930\u094d\u092d\u0930 \u0930\u0939\u0928\u093e \u0939\u0948\u0964", "\u0915\u094d\u092f\u093e \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u092e\u0947\u0902 \u092a\u0939\u0932\u0947 \u0938\u0947 \u0909\u092a\u0938\u094d\u0925\u093f\u0924 \u0915\u093f\u0938\u0940 \u0935\u093f\u0936\u0947\u0937 \u092c\u093e\u092f\u094b\u090f\u0915\u094d\u091f\u093f\u0935\u093f\u091f\u0940 \u090f\u0902\u0921\u092a\u0949\u0907\u0902\u091f (\u0909\u0926\u093e. $IC_{50}$ \u092f\u093e $K_i$) \u0915\u0947 \u0938\u0902\u0926\u0930\u094d\u092d \u092e\u0947\u0902 \u0921\u093f\u0938\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u0930\u094d\u0938 \u0915\u093e \u0926\u094d\u0935\u093f\u091a\u0930 (bivariate) \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0906\u0935\u0936\u094d\u092f